    // Get it from the prefs.
    return this.getServerByKey(defaultServerKey);
  }

  // No pref set, so set the first one as default, and return it.
  if (this.servers.length > 0) {
    this.defaultServer = this.servers[0];
    return this.servers[0];
  }
